Here's a basic implementation of an upvote/downvote system for a comment board using Node.js (Express), PostgreSQL, and React. This system will track votes per user and display vote counts.

### 1. Database Schema (SQL)
```sql
-- comments table
CREATE TABLE comments (
    id SERIAL PRIMARY KEY,
    content TEXT NOT NULL,
    upvotes INTEGER DEFAULT 0,
    downvotes INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT NOW()
);

-- votes table (to track individual user votes)
CREATE TABLE votes (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id),
    comment_id INTEGER NOT NULL REFERENCES comments(id),
    vote_type VARCHAR(3) CHECK (vote_type IN ('up', 'down')),
    UNIQUE (user_id, comment_id)
);
```

### 2. Backend API (Node.js/Express)
```javascript
const express = require('express');
const { Pool } = require('pg');
const cors = require('cors');
const helmet = require('helmet');

const app = express();
const port = 3001;

// Database connection
const pool = new Pool({
    user: 'your_user',
    host: 'localhost',
    database: 'your_db',
    password: 'your_password',
    port: 5432,
});

app.use(express.json());
app.use(cors());
app.use(helmet());

// Get all comments
app.get('/api/comments', async (req, res) => {
    try {
        const result = await pool.query('SELECT * FROM comments ORDER BY created_at DESC');
        res.json(result.rows);
    } catch (err) {
        console.error(err);
        res.status(500).send('Server error');
    }
});

// Create new comment
app.post('/api/comments', async (req, res) => {
    const { content } = req.body;
    try {
        const result = await pool.query(
            'INSERT INTO comments (content) VALUES ($1) RETURNING *',
            [content]
        );
        res.status(201).json(result.rows[0]);
    } catch (err) {
        console.error(err);
        res.status(400).send('Invalid data');
    }
});

// Upvote/Downvote
app.post('/api/comments/:id/vote', async (req, res) => {
    const { voteType } = req.body;
    const { id } = req.params;
    const userId = req.user.id; // Assume user authentication is handled

    try {
        // Check existing vote for this user
        const existingVote = await pool.query(
            'SELECT vote_type FROM votes WHERE user_id = $1 AND comment_id = $2',
            [userId, id]
        );

        if (existingVote.rows.length > 0) {
            // Update existing vote
            await pool.query(
                'UPDATE votes SET vote_type = $3 WHERE user_id = $1 AND comment_id = $2',
                [userId, id, voteType]
            );

            // Update comment counts
            if (existingVote.rows[0].vote_type === voteType) {
                // User changed their vote type
                await updateVoteCount(id, existingVote.rows[0].vote_type, -1);
                await updateVoteCount(id, voteType, 1);
            } else {
                // User switched vote direction
                await updateVoteCount(id, existingVote.rows[0].vote_type, -1);
                await updateVoteCount(id, voteType, 1);
            }
        } else {
            // Add new vote
            await pool.query(
                'INSERT INTO votes (user_id, comment_id, vote_type) VALUES ($1, $2, $3)',
                [userId, id, voteType]
            );
            await updateVoteCount(id, voteType, 1);
        }

        res.sendStatus(200);
    } catch (err) {
        console.error(err);
        res.status(500).send('Vote failed');
    }
});

