Here's a clean and responsive Login/Signup form using HTML/CSS with Bootstrap 5 styling. You can copy and paste this code:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Login / Signup Form</title>
    <!-- Bootstrap CSS -->
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
    <style>
        body {
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 20px;
            background-color: #f8f9fa;
        }
        .card {
            width: 100%;
            max-width: 450px;
            border: none;
            box-shadow: 0 4px 8px rgba(0,0,0,0.1);
        }
        .tab {
            margin: 20px 0;
        }
        .tab button {
            width: 50%;
            border: none;
            border-bottom: 3px solid transparent;
            padding: 12px;
            cursor: pointer;
            font-weight: 500;
            transition: all 0.3s ease;
        }
        .tab button.active {
            border-bottom: 3px solid #0d6efd;
            color: #0d6efd;
        }
        .form-group {
            margin-bottom: 15px;
        }
        .form-control {
            border-radius: 0;
            border: 1px solid #ced4da;
        }
        .social-btns {
            margin: 20px 0;
        }
        .social-btns button {
            width: 100%;
            margin: 5px 0;
            border-radius: 0;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="card">
            <div class="card-body">
                <div class="tab">
                    <button type="button" class="active" onclick="showForm('login')">Login</button>
                    <button type="button" onclick="showForm('signup')">Sign Up</button>
                </div>

                <!-- Login Form -->
                <div id="loginForm" style="display: block;">
                    <h2 class="text-center mb-4">Welcome Back</h2>
                    <form>
                        <div class="form-group">
                            <label for="loginEmail">Email address</label>
                            <input type="email" class="form-control" id="loginEmail" required>
                        </div>
                        <div class="form-group">
                            <label for="loginPassword">Password</label>
                            <input type="password" class="form-control" id="loginPassword" minlength="8" required>
                        </div>
                        <div class="d-flex justify-content-between">
                            <div class="form-check">
                                <input type="checkbox" class="form-check-input" id="rememberMe">
                                <label class="form-check-label" for="rememberMe">Remember me</label>
                            </div>
                            <a href="#" class="text-muted">Forgot password?</a>
                        </div>
                        <button type="submit" class="btn btn-primary w-100 mt-3">Login</button>
                    </form>
                    <div class="social-btns mt-3">
                        <button type="button" class="btn btn-light"><i class="fab fa-google"></i> Sign in with Google</button>
                        <button type="button" class="btn btn-light"><i class="fab fa-facebook-f"></i> Sign in with Facebook</button>
                    </div>
                </div>

                <!-- Signup Form -->
                <div id="signupForm" style="display: none;">
                    <h2 class="text-center mb-4">Create Account</h2>
                    <form>
                        <div class="form-group">
                            <label for="signupName">Name</label>
                            <input type="text" class="form-control" id="signupName" required>
                        </div>
                        <div class="form-group">
                            <label for="signupEmail">Email address</label>
                            <input type="email" class="form-control" id="signupEmail" required>
                        </div>
                        <div class="form-group">
                            <label for="signupPassword">Password</label>
                            <input type="password" class="form-control" id="signupPassword" minlength="8" required>
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input type="password" class="form-control" id="confirmPassword" minlength="8" required>
                        </div>
                        <div class="form-check mb-3">
                            <input type="checkbox" class="form-check-input" id="termsCheck" required>
                            <label class="form-check-label" for="termsCheck">I agree to the <a href="#">Terms & Conditions</a></label>
                        </div>
                        <button type="submit" class="btn btn-primary w-100">Sign Up</button>
                    </form>
                    <div class="social-btns mt-3">
                        <button type="button" class="btn btn-light"><i class="fab fa-google"></i> Sign up with Google</button>
                        <button type="button" class="btn btn-light"><i class="fab fa-facebook-f"></i> Sign up with Facebook</button>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <!-- Bootstrap JS and dependencies -->
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
    <script src="https://kit.fontawesome.com/your-fontawesome-kit.js" crossorigin="anonymous"></script>
    <script>
        function showForm(formType) {
            document.getElementById('loginForm').style.display = formType === 'login' ? 'block' : 'none';
            document.getElementById('signupForm').style.display = formType === 'signup' ? 'block' : 'none';

            // Update button states
            document.querySelectorAll('.tab button').forEach(btn => btn.classList.remove('active'));
            document.querySelector(`.tab button[onclick="showForm('${formType}')"]`).classList.add('active');
        }
    </script>
</body>
</html>
```

